# tests/test_template_new.py
"""A new project is generated by task from the template on GitHub, pinned (D.54).

Copier records the source it is given as _src_path and the ref as _commit: a laptop
path breaks copier update anywhere else, and an unpinned ref lets Copier pick its own
latest. policies/runs/template/new decides over the request; these prove each rule bites,
and that a correct request is allowed.
"""

from __future__ import annotations

import json
import os
from collections.abc import Iterator
from contextlib import contextmanager
from pathlib import Path

import pytest
from plumbum import local

import template_new
from opa import denials
from project_identity import load
from template_new import TemplateRequest, main, request

ENTRYPOINT = "data.runs.template.new.deny"
# COMPOSED, NOT WRITTEN: the PII gate reads any user-at-host literal as an email (D.57).
GITHUB_SSH = "git" + "@" + "github.com:"
SHA = "0123456789abcdef0123456789abcdef01234567"
REPO = Path(__file__).resolve().parent.parent
# WHAT A PROMPT-FREE CLONE NEEDS IN THE ENVIRONMENT COPIER'S GIT RUNS IN (D.57, D.247).
PROMPT_KEYS = ("GIT_TERMINAL_PROMPT", "GCM_INTERACTIVE", "GIT_SSH_COMMAND")


def _decide(made: TemplateRequest) -> list[str]:
    return denials(ENTRYPOINT, {"template_request": made.model_dump(mode="json")})


def test_an_unpinned_ref_is_refused(tmp_path: Path) -> None:
    for ref in ("HEAD", "develop", "v1", SHA[:7]):
        found = _decide(request(tmp_path / "new", ref))
        assert any("ERR_TEMPLATE_UNPINNED" in denial for denial in found), (ref, found)


def test_an_occupied_destination_is_refused(tmp_path: Path) -> None:
    (tmp_path / "taken").mkdir()
    (tmp_path / "taken" / "README.md").write_text("here\n", encoding="utf-8")
    found = _decide(request(tmp_path / "taken", SHA))
    assert any("ERR_TEMPLATE_DESTINATION_OCCUPIED" in denial for denial in found), found


def test_a_destination_inside_the_source_is_refused() -> None:
    found = _decide(request(REPO / "generated", SHA))
    assert any("ERR_TEMPLATE_DESTINATION_INSIDE" in denial for denial in found), found


def test_a_pinned_request_to_an_empty_destination_is_allowed(tmp_path: Path) -> None:
    made = request(tmp_path / "new", SHA)
    assert made.transport.startswith(GITHUB_SSH), made.transport
    assert _decide(made) == []


def test_the_task_refuses_before_generating(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """An unpinned request never reaches Copier: refused, and nothing is created.

    GENERATION IS MADE IMPOSSIBLE, NOT MERELY UNOBSERVED (D.68): with the refusal
    broken, the real Copier cloned from GitHub and a mutation run waited on a
    credential prompt. Replaced as test_generation_runs_without_any_prompt does.
    """

    def reached(*_: object, **__: object) -> None:
        raise AssertionError("generation was reached for a refused request")

    monkeypatch.setattr(template_new, "run_copy", reached)
    destination = tmp_path / "never"
    assert main([str(destination), "HEAD"]) == 2
    assert not destination.exists()


def test_the_source_is_the_declared_repository_over_ssh(tmp_path: Path) -> None:
    """Every clone from this machine goes over SSH; HTTPS stopped at a prompt (D.57)."""
    declared = load(REPO).repository.removeprefix("https://github.com/")
    assert request(tmp_path / "new", SHA).transport == f"{GITHUB_SSH}{declared}.git"


def test_a_source_that_is_not_ssh_is_refused(tmp_path: Path) -> None:
    made = request(tmp_path / "new", SHA)
    https = made.model_copy(update={"transport": "https://github.com/example/template.git"})
    found = _decide(https)
    assert any("ERR_TEMPLATE_SOURCE_NOT_SSH" in denial for denial in found), found


def test_generation_runs_without_any_prompt(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """git and ssh prompt on the terminal; a clone that needs input must fail, not wait."""
    seen: dict[str, str] = {}

    def record(*_: object, **__: object) -> None:
        for key in ("GIT_TERMINAL_PROMPT", "GCM_INTERACTIVE", "GIT_SSH_COMMAND"):
            seen[key] = os.environ.get(key, "")

    for key in ("GIT_TERMINAL_PROMPT", "GCM_INTERACTIVE", "GIT_SSH_COMMAND"):
        monkeypatch.delenv(key, raising=False)
    monkeypatch.setattr(template_new, "run_copy", record)
    assert main([str(tmp_path / "new"), SHA]) == 0
    assert seen["GIT_TERMINAL_PROMPT"] == "0", seen
    assert seen["GCM_INTERACTIVE"] == "never", seen
    assert "BatchMode=yes" in seen["GIT_SSH_COMMAND"], seen
    assert "GIT_TERMINAL_PROMPT" not in os.environ, "the environment leaked past the call"


def test_a_failed_clone_is_reported_as_data(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    """A clone that fails reports why, as command-outcome/v1, never as a traceback."""

    def refuse(*_: object, **__: object) -> None:
        raise RuntimeError("Permission denied (publickey)")

    monkeypatch.setattr(template_new, "run_copy", refuse)
    assert main([str(tmp_path / "new"), SHA]) == 1
    outcome = json.loads(capsys.readouterr().out)
    assert outcome["code"] == "generation_failed", outcome
    assert "publickey" in outcome["message"], outcome


def test_the_source_is_recorded_over_https_and_cloned_over_ssh(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Copier records what it is given, so it is given HTTPS; git rewrites it to SSH (D.64).

    An SSH source in .copier-answers.yml is a user-at-host string the PII gate refuses in
    every generated project. The rewrite comes from the environment, for this call only.
    """
    seen: dict[str, object] = {}

    def record(src_path: str, *_: object, **__: object) -> None:
        seen["src_path"] = src_path
        count = int(os.environ.get("GIT_CONFIG_COUNT", "0"))
        seen["rewrites"] = {
            os.environ[f"GIT_CONFIG_KEY_{i}"]: os.environ[f"GIT_CONFIG_VALUE_{i}"]
            for i in range(count)
        }

    monkeypatch.delenv("GIT_CONFIG_COUNT", raising=False)
    monkeypatch.setattr(template_new, "run_copy", record)
    assert main([str(tmp_path / "new"), SHA]) == 0
    declared = load(REPO).repository
    owner_repo = declared.removeprefix("https://github.com/")
    assert seen["src_path"] == f"{declared}.git", seen
    assert "@" not in str(seen["src_path"]), seen
    ssh = f"{GITHUB_SSH}{owner_repo}.git"
    assert seen["rewrites"] == {f"url.{ssh}.insteadOf": f"{declared}.git"}, seen
    assert "GIT_CONFIG_COUNT" not in os.environ, "the rewrite leaked past the call"


@contextmanager
def _cleared(monkeypatch: pytest.MonkeyPatch, *keys: str) -> Iterator[None]:
    """Absent from os.environ and from plumbum's own copy, so nothing ambient can pass.

    plumbum's env(), entered with nothing to set, keeps a copy and restores it on exit.
    """
    for key in keys:
        monkeypatch.delenv(key, raising=False)
    with local.env():
        for key in keys:
            if key in local.env:
                del local.env[key]
        yield


def _child_environment(*keys: str) -> dict[str, str | None]:
    """The named variables as a child of plumbum's local sees them: where Copier runs git.

    ONLY THE NAMED KEYS ARE KEPT: the rest of a real environment never reaches a report.
    """
    listed = local["env"]()
    found = dict(line.split("=", 1) for line in listed.splitlines() if "=" in line)
    return {key: found.get(key) for key in keys}


def test_copiers_git_sees_the_ssh_rewrite(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    """D.247: inside the block, the git Copier runs resolves the HTTPS source to SSH.

    git ls-remote --get-url applies url.insteadOf and exits without reaching the remote.
    """
    made = request(tmp_path / "new", SHA)
    with (
        _cleared(monkeypatch, "GIT_CONFIG_COUNT"),
        template_new._non_interactive((made.transport, made.source)),
    ):
        resolved = local["git"]("ls-remote", "--get-url", made.source).strip()
    assert resolved == made.transport, resolved


def test_copiers_git_never_prompts(monkeypatch: pytest.MonkeyPatch) -> None:
    """D.247: inside the block, a child of the channel Copier's git runs in has no prompts."""
    with _cleared(monkeypatch, *PROMPT_KEYS), template_new._non_interactive():
        seen = _child_environment(*PROMPT_KEYS)
    assert seen["GIT_TERMINAL_PROMPT"] == "0", seen
    assert seen["GCM_INTERACTIVE"] == "never", seen
    assert "BatchMode=yes" in (seen["GIT_SSH_COMMAND"] or ""), seen


def test_copiers_git_environment_is_restored_after_the_call(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """D.247: the rewrite reaches the channel for the call only, and is gone after it."""
    watched = ("GIT_CONFIG_COUNT", "GIT_TERMINAL_PROMPT")
    with _cleared(monkeypatch, "GIT_CONFIG_COUNT", *PROMPT_KEYS):
        with template_new._non_interactive(("ssh-form", "https-form")):
            inside = _child_environment(*watched)
        after = _child_environment(*watched)
    assert inside["GIT_CONFIG_COUNT"] == "1", inside
    assert after == {"GIT_CONFIG_COUNT": None, "GIT_TERMINAL_PROMPT": None}, after
